#!/usr/bin/env python3

import RPi.GPIO as GPIO
import spidev
import time
import argparse
import logging
import json
import signal
import sys
import os
import random
import threading
import queue
import socket
import json
import datetime
import math

# Constants
DEFAULT_SAMPLING_RATE = 500  # Hz
DEFAULT_MOVING_AVERAGE_WINDOW = 10
DEFAULT_THRESHOLD = 0.5
DEFAULT_HYSTERESIS = 0.05
DEFAULT_OUTPUT_PIN = 0  # Disabled
DEFAULT_LOG_FILE = "sound_level.log"
DEFAULT_CLOUD_API_URL = "http://localhost:5000/upload"
DEFAULT_CLOUD_API_KEY = "your_api_key"

# Global variables
running = True
spi = None
output_pin = None
cloud_queue = queue.Queue()

# Logging setup
logging.basicConfig(filename=DEFAULT_LOG_FILE, level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global running
    logging.info("Received signal, shutting down gracefully...")
    running = False
    GPIO.cleanup()
    spi.close()
    sys.exit(0)

# Register signal handlers for graceful shutdown
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to read data from MCP3008 ADC
def read_mcp3008(channel):
    """Reads data from the specified channel of the MCP3008 ADC."""
    try:
        spi.xfer2([1, (8 + channel) << 4, 0])
        adc_out = ((spi.xfer2([1, (8 + channel) << 4, 0]) & 3) << 8) + spi.xfer2([1, (8 + channel) << 4, 0])[1]
        return adc_out
    except Exception as e:
        logging.error(f"Error reading from MCP3008 channel {channel}: {e}")
        return None

# Function to calculate moving average filter
def moving_average(data, window_size):
    """Calculates the moving average of a list of data points."""
    if len(data) < window_size:
        return sum(data) / len(data) if data else 0
    return sum(data[-window_size:]) / window_size

# Function to normalize sound level
def normalize_sound_level(sound_level):
    """Normalizes the sound level to a 0.0-1.0 range."""
    return sound_level / 100.0

# Function to upload data to cloud API
def upload_to_cloud(data):
    """Uploads the data to the cloud API."""
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            sock.connect((DEFAULT_CLOUD_API_URL, DEFAULT_CLOUD_API_PORT))
            sock.sendall(json.dumps(data).encode('utf-8'))
            response = sock.recv(1024)
            logging.info(f"Cloud API response: {response.decode('utf-8')}")
    except Exception as e:
        logging.error(f"Error uploading to cloud API: {e}")

# Function to simulate sensor data
def simulate_sensor_data():
    """Simulates sound level readings with some random variation."""
    return random.uniform(0.0, 1.0)

# Function to read cloud data
def read_cloud_data():
    """Reads data from the cloud API."""
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            sock.connect((DEFAULT_CLOUD_API_URL, DEFAULT_CLOUD_API_PORT))
            sock.sendall(b'GET /upload')
            response = sock.recv(1024)
            logging.info(f"Cloud API response: {response.decode('utf-8')}")
            if response.startswith(b'HTTP/1.1 200 OK'):
                data = json.loads(response[7:])
                logging.info(f"Cloud API data: {data}")
                return data
            else:
                logging.warning(f"Cloud API error: {response.decode('utf-8')}")
                return None
    except Exception as e:
        logging.error(f"Error reading cloud data: {e}")
        return None

