        logging.info(f"Cloud upload complete: {data}")
    except Exception as e:
        logging.error(f"Error handling cloud upload: {e}")

# Function to handle cloud uploads with exponential backoff
def retry_cloud_upload(data, max_retries=3, delay=2):
    """Retries cloud uploads with exponential backoff."""
    retries = 0
    while retries < max_retries:
        try:
            with open(DEFAULT_LOG_FILE, "a") as f:
                f.write(f"{datetime.datetime.now().isoformat()} - {data}\n")
            logging.info(f"Cloud upload complete: {data}")
            return True
        except Exception as e:
            logging.error(f"Error handling cloud upload: {e}")
            retries += 1
            time.sleep(delay)
    logging.error(f"Max retries reached for cloud upload: {data}")
    return False

