#!/usr/bin/env python3

import RPi.GPIO as GPIO
import spidev
import time
import argparse
import json
import socket
import threading
import queue
import logging
import os
import signal
import sys

# Constants
DEFAULT_MOISTURE_THRESHOLD = 30
DEFAULT_VALVE_PIN = 17
DEFAULT_SPI_CHANNEL = 0
DEFAULT_SPI_REFERENCE = 3.3
DEFAULT_LOG_FILE = "irrigation.log"
DEFAULT_WEB_PORT = 8080

# Global variables
moisture_queue = queue.Queue()
running = True

# Custom exception classes
class SensorError(Exception):
    pass

class SPIError(Exception):
    pass

class IrrigationError(Exception):
    pass

# Configuration management functions
def parse_arguments():
    parser = argparse.ArgumentParser(description="Smart Irrigation System")
    parser.add_argument("--moisture_threshold", type=int, default=DEFAULT_MOISTURE_THRESHOLD, help="Soil moisture threshold (percentage)")
