import time
import threading
import json
import os
import logging
import paho.mqtt.client as mqtt
import spidev

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SPI_BUS = 0
SPI_CHIP_SELECT = 0
SPI_MAX_SPEED = 50000
MQTT_BROKER = "mqtt.example.com"
MQTT_PORT = 1883
MQTT_TOPIC = "sensor/temperature_humidity"
MQTT_KEEPALIVE = 60

# Global variables
spi = None
mqtt_client = None
running = True

# Function to initialize SPI
def initialize_spi():
    global spi
    spi = spidev.SpiDev()
    spi.open(SPI_BUS, SPI_CHIP_SELECT)
    spi.max_speed_hz = SPI_MAX_SPEED
    logging.info("SPI initialized successfully.")

# Function to initialize MQTT client
def initialize_mqtt_client():
    global mqtt_client
    mqtt_client = mqtt.Client()
    mqtt_client.connect(MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE)
    mqtt_client.loop_start()
    logging.info("MQTT client connected successfully.")

# Function to read data from MCP3008 ADC
def read_mcp3008(channel):
    try:
        # MCP3008 requires a 3-byte transfer
        response = spi.xfer2([1, (8 + channel) << 4, 0])
        adc_value = ((response[1] & 3) << 8) + response[2]
        return adc_value
    except Exception as e:
        logging.error(f"Error reading from MCP3008: {e}")
        return None

# Function to publish sensor data to MQTT
def publish_sensor_data(channel, raw_value):
    try:
        payload = {"channel": channel, "raw": raw_value}
        mqtt_client.publish(MQTT_TOPIC, json.dumps(payload))
        logging.info(f"Published data to MQTT: {payload}")
    except Exception as e:
        logging.error(f"Error publishing to MQTT: {e}")

# Function to handle MQTT messages
def on_message(client, userdata, message):
    try:
        payload = message.payload.decode()
        logging.info(f"Received MQTT message: {payload}")
        data = json.loads(payload)
        channel = data.get("channel")
        raw_value = data.get("raw")
        if channel:
            if raw_value is not None:
                raw_value = int(raw_value)
                publish_sensor_data(channel, raw_value)
            else:
