#!/usr/bin/env python3

import RPi.GPIO as GPIO
import time
import logging
import signal
import sys
import threading
import queue
import json
import os

# Constants
SERVO_MIN_ANGLE = 0
SERVO_MAX_ANGLE = 90
SERVO_DEGREE_STEP = 1
DISTANCE_SENSOR_TRIGGER_PIN = 23
DISTANCE_SENSOR_ECHO_PIN = 24
SERVO_CONTROL_PIN = 25
BALANCE_TOLERANCE = 3
MAX_ERROR = 25
SLEEP_INTERVAL = 0.1
LOGGING_LEVEL = logging.INFO

# Global variables
balance_beam_controller = None
distance_queue = queue.Queue()
running = True

# Configure logging
logging.basicConfig(level=LOGGING_LEVEL, format='%(asctime)s - %(levelname)s - %(message)s')

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global running
    logging.info("Received signal, shutting down gracefully...")
    running = False
    GPIO.cleanup()
    sys.exit(0)

# Register signal handler for Ctrl+C
signal.signal(signal.SIGINT, signal_handler)

# Function to read distance from the sensor
def read_distance():
    try:
        distance = distance_queue.get(timeout=1)  # Wait for 1 second, timeout
        return distance
    except queue.Empty:
        return None
    except Exception as e:
        logging.error(f"Error reading distance: {e}")
        return None

# Function to control the servo
def control_servo(angle):
    try:
        GPIO.output(SERVO_CONTROL_PIN, GPIO.HIGH)
        GPIO.output(SERVO_CONTROL_PIN, GPIO.LOW)
        GPIO.output(SERVO_CONTROL_PIN, GPIO.HIGH)
        GPIO.output(SERVO_CONTROL_PIN, angle)
    except Exception as e:
        logging.error(f"Error controlling servo: {e}")

# Function to calculate error
def calculate_error(distance, setpoint):
    error = distance - setpoint
    return error

# Function to update PID controller
def update_pid(error, last_error, integral, derivative, setpoint):
    global running
    if running:
        integral += error
        derivative = error - last_error
        output = Kp * error + Ki * integral + Kd * derivative
        last_error = error
        return output, last_error, integral, derivative
    else:
        return 0, 0, 0, 0

# Function to control servo
def control_servo_loop(servo_angle):
    global running
    try:
        control_servo(servo_angle)
    except Exception as e:
        logging.error(f"Error controlling servo: {e}")

# Function to read and process sensor data
def process_sensor_data():
    global running
    while running:
        distance = read_distance()
        if distance is not None:
            error = calculate_error(distance, 25)
            pid_output, last_error, integral, derivative = update_pid(error, last_error, 0, 0, 25)
            control_servo_loop(pid_output)
            distance_queue.put((distance, pid_output))
        time.sleep(SLEEP_INTERVAL)

# Function to handle sensor data
def handle_sensor_data(distance, pid_output):
    global running
    if pid_output is not None:
        if pid_output > 0:
