#!/usr/bin/env python3

# Raspberry Pi Proximity Obstacle Avoidance System
# Author: Bard
# Date: October 26, 2023
# Description: This program reads proximity sensors from a PCF8574 I2C expander and prints detected obstacles.

import time
import smbus
import RPi.GPIO as GPIO

# I2C address of the PCF8574 expander
PCF8574_ADDRESS = 0x27

# GPIO pin connected to the PCF8574 INT line
PCF8574_INT_PIN = 17

# I2C bus number
I2C_BUS_NUMBER = 1

# Initialize I2C bus
try:
    bus = smbus.SMBus(I2C_BUS_NUMBER)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    exit(1)

# Setup GPIO mode and pin
GPIO.setmode(GPIO.BCM)
GPIO.setup(PCF8574_INT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

# Function to read a byte from the PCF8574 expander
def read_pcf8574_byte(address):
    try:
        # Read the first byte of the register
        data = bus.read_byte_data(PCF8574_ADDRESS, address)
        # Check for a valid byte
        if data & 0x80:
            # Check for falling edge interrupt
            if data & 0x40:
                # Check for falling edge interrupt
                if data & 0x10:
                    # Check for falling edge interrupt
                    if data & 0x08:
                        # Check for falling edge interrupt
                        if data & 0x04:
                            # Check for falling edge interrupt
                            if data & 0x02:
                                # Check for falling edge interrupt
                                if data & 0x01:
                                    return 1
        return 0
    except Exception as e:
        print(f"Error reading PCF8574 byte: {e}")
        return 0

# Function to read proximity sensors
def read_proximity_sensors():
    try:
        # Read all 8 proximity sensors
        proximity_sensors = []
        for i in range(8):
            proximity_sensors.append(read_pcf8574_byte(PCF8574_ADDRESS + (i << 1)))
        return proximity_sensors
    except Exception as e:
        print(f"Error reading proximity sensors: {e}")
        return []

# Function to print detected obstacles
def print_obstacle_detected(proximity_sensors):
    try:
        # Print the number of obstacles detected
        print("Obstacle detected by sensor [N]")
        for i, sensor_value in enumerate(proximity_sensors):
            if sensor_value == 0:
                print(f"Sensor {i+1}: {sensor_value}")
    except Exception as e:
        print(f"Error printing obstacles: {e}")

# Main loop
try:
    while True:
        # Read proximity sensors
        proximity_sensors = read_proximity_sensors()

        # Print detected obstacles
        print_obstacle_detected(proximity_sensors)

        # Wait for 1 second
        time.sleep(1)

except KeyboardInterrupt:
    # Handle Ctrl+C gracefully
    print("Exiting program...")

except Exception as e:
    print(f"An unexpected error occurred: {e}")

finally:
    # Clean up GPIO resources
    GPIO.cleanup()
    print("GPIO resources cleaned up.")

