import cv2
import numpy as np
import time

# Constants
FRAME_RATE = 15
WARM_UP_DELAY = 2
SAVE_DELAY = 2
BASELINE_THRESHOLD = 10

# Initialize baseline
baseline_avg = None

def initialize_camera():
    """Initializes the camera and returns the capture object."""
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")
        return cap
    except IOError as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(cap):
    """Captures a frame from the camera and returns it as a numpy array."""
    ret, frame = cap.read()
    if not ret:
        raise IOError("Failed to capture frame")
    return frame

def compute_average_pixel_value(frame):
    """Computes the average pixel value of a frame."""
    return np.mean(frame[:, :, 0:3])

def compare_pixel_differences(baseline_avg, current_avg):
    """Compares the absolute difference between two average pixel values."""
    return abs(baseline_avg - current_avg) > BASELINE_THRESHOLD

def save_frame(frame, filename):
    """Saves a frame to a file."""
    try:
        cv2.imwrite(filename, frame)
    except Exception as e:
        print(f"Error saving frame: {e}")

def main():
    """Main function to capture and process frames."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        print("Starting motion detection...")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, 64)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 64)

        while True:
            start_time = time.time()
            frame = capture_frame(camera)
            current_avg = compute_average_pixel_value(frame)
            if baseline_avg is None or compare_pixel_differences(baseline_avg, current_avg):
                baseline_avg = current_avg
                save_frame(frame, "motion.jpg")
                print(f"Motion detected! Frame saved: motion.jpg")
            end_time = time.time()
            elapsed_time = end_time - start_time
            print(f"Elapsed time: {elapsed_time:.2f} seconds")
            time.sleep(SAVE_DELAY)

    except KeyboardInterrupt:
        print("Exiting...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if camera:
            camera.release()

if __name__ == "__main__":
    main()

