import cv2
import numpy as np
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
MSE_THRESHOLD = 100

def capture_video(camera_id=0, resolution=(32, 32)):
    """Captures video from the specified camera and returns the frame."""
    try:
        cap = cv2.VideoCapture(camera_id)
        if not cap.isOpened():
            raise IOError(f"Cannot open webcam {camera_id}")
        cap.set(3, resolution[0])
        cap.set(4, resolution[1])
        return cap.read()
    except IOError as e:
        logging.error(f"Error capturing video: {e}")
        return None
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
        return None

def calculate_mse(frame1, frame2):
    """Calculates the Mean Squared Error (MSE) between two frames."""
    try:
        mse = cv2.meanSquaredDistance(frame1, frame2)
        return mse
    except Exception as e:
        logging.exception(f"Error calculating MSE: {e}")
        return None

def process_frame(frame, previous_frame, mse_threshold):
    """Processes a single frame to detect motion."""
    try:
        blurred_frame = cv2.GaussianBlur(frame, (3, 3), 0)
        compensated_frame = cv2.cvtColor(blurred_frame, cv2.COLOR_BGR2GRAY)
        gray_frame = cv2.cvtColor(blurred_frame, cv2.COLOR_BGR2GRAY)
        mse = calculate_mse(compensated_frame, gray_frame)
        if mse is not None:
            logging.info(f"MSE: {mse}")
            if mse > mse_threshold:
                return True
        return False
    except Exception as e:
        logging.exception(f"Error processing frame: {e}")
        return False

def display_windows(frame, previous_frame, mse_threshold):
    """Displays the current frame, previous frame, and MSE."""
    cv2.imshow('Original', frame)
    cv2.imshow('Compensated', cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY))
    cv2.imshow('Gray', cv2.cvtColor(gray_frame, cv2.COLOR_BGR2GRAY))
    cv2.imshow('Edge', cv2.Canny(cv2.cvtColor(blurred_frame, cv2.COLOR_BGR2GRAY), 100, 200))
    if process_frame(frame, previous_frame, mse_threshold):
        logging.info("Motion detected!")

def main():
    """Main function to capture and display video."""
    previous_frame = None
    try:
        while True:
            frame = capture_video()
            if frame is None:
                break

            display_windows(frame, previous_frame, MSE_THRESHOLD)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

            previous_frame = frame.copy()

    except KeyboardInterrupt:
        logging.info("Exiting program.")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
    finally:
        if 'cap' in locals() and cap is not None:
            cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

