def open_port(b, d, p, s, fc):
    global port
    try:
        port = serial.Serial(b, d, p, s, fc=fc)
    except:
        return False
    return True

def close_port(port):
    global port
    try:
        port.close()
    except:
        pass

def send_data(port, data):
    try:
        port.write(data)
    except:
        pass

def main():
    global port
    try:
        if not open_port(b, d, p, s, fc):
            exit()
        while True:
            line = input('X> ').strip()
            if line == 'q':
                break
            send_data(port, line)
            if port.in_waiting:
                print(f'Sent: {len(line)} bytes')
            else:
                print('No data to send')
    except:
        pass
    finally:
        close_port(port)

