Z_RANGE = 0
X_MIN = 0
Y_MIN = 0
Z_MIN = 0
X_MAX = CAMERA_WIDTH
Y_MAX = CAMERA_HEIGHT
Z_MAX = CAMERA_HEIGHT

# Global variables
encodings = {}  # Dictionary to store face encodings
camera = None  # Picamera2 object
relay_pin = 17  # GPIO pin for the relay
relay_on = False  # Flag to control relay state
debounce_interval = 2  # Debounce interval in seconds

# Custom exception classes
class CameraInitializationError(Exception):
    pass

class RelayControlError(Exception):
    pass

class FaceRecognitionError(Exception):
    pass

# Configuration management functions
def parse_arguments():
    parser = argparse.ArgumentParser(description="Raspberry Pi Camera-Based Smart Home Security System")
    parser.add_argument("--log_level", default="INFO", choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"], help="Logging level")
    parser.add_argument("--motion_threshold", type=int, default=500, help="Motion detection threshold")
    parser.add_argument("--confidence_threshold", type=float, default=0.6, help="Face recognition confidence threshold")
    parser.add_argument("--camera_width", type=int, default=CAMERA_WIDTH, help="Camera width")
    parser.add_argument("--camera_height", type=int, default=CAMERA_HEIGHT, help="Camera height")
    parser.add_argument("--relay_pin", type=int, default=relay_pin, help="GPIO pin for the relay")
    parser.add_argument("--encodings_file", type=str, default="encodings.json", help="Path to the encodings file")
    return parser.parse_args()

# Resource management functions
def initialize_camera(width, height, format):
    global camera
    try:
        camera = Picamera2()
        config = camera.create_still_configuration(main={"size": (width, height), "format": format})
        camera.configure(config)
        camera.start()
        time.sleep(2)  # Warm-up time
        logging.info("Camera initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return False

def initialize_relay(pin):
    global relay_pin
    try:
        gpio.setmode(gpio.BCM)
        gpio.setup(pin, gpio.OUT)
        logging.info("Relay initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Relay initialization failed: {e}")
        return False

def initialize_encodings(encodings_file):
    global encodings
    try:
        with open(encodings_file, "r") as f:
            encodings = json.load(f)
        logging.info("Encodings loaded successfully.")
    except FileNotFoundError:
        logging.error(f"Encodings file not found: {encodings_file}")
        encodings = {}
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON in encodings file: {encodings_file}")
        encodings = {}
    except Exception as e:
        logging.error(f"Error loading encodings: {e}")
        encodings = {}

# Image processing functions
def process_frame(frame):
    global camera, encodings
    try:
        image = Image.fromarray(frame)
        draw = ImageDraw.Draw(image)
        font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 16)
        color = (255, 255, 255)
        draw.text((10, 10), "Motion Detected", font=font, fill=color)
        return image
    except Exception as e:
        logging.error(f"Error processing frame: {e}")
        return None

def calculate_pixel_difference(frame1, frame2):
    try:
        diff = np.abs(frame1 - frame2)
        return np.sum(diff > 10)
    except Exception as e:
        logging.error(f"Error calculating pixel difference: {e}")
        return 0

def detect_motion(frame, threshold):
    return calculate_pixel_difference(frame, frame.copy()) > threshold

def detect_face(frame, encodings):
    try:
        face_candidates = []
        for face_id, face_encodings in encodings.items():
            if len(face_encodings) == 0:
                continue
            min_distance = float('inf')
            min_index = 0
            for i, face_encodings_copy in enumerate(face_encodings):
                distance = calculate_pixel_difference(face_encodings_copy, face_encodings)
                if distance > min_distance:
                    min_distance = distance
                    min_index = i
            face_candidates.append(face_encodings[min_index])
        return face_candidates
    except Exception as e:
        logging.error(f"Error detecting face: {e}")
        return []

def recognize_face(frame, face_candidates):
    try:
        if len(face_candidates) == 0:
            return False

        best_candidate = face_candidates[0]
        confidence = 0
        for candidate in face_candidates:
            confidence += calculate_pixel_difference(candidate, face_encodings[0])
        confidence /= len(face_candidates)

        if confidence > 0.6:
            return True
        else:
            return False
    except Exception as e:
        logging.error(f"Error recognizing face: {e}")
        return False

