logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_FRAME_RATE = 10
DEFAULT_LOW_RESOLUTION = "rgb888"
DEFAULT_HIGH_RESOLUTION = "jpeg"
DEFAULT_LOW_RESOLUTION = "jpeg"
DEFAULT_MOTION_DETECTION_FUNCTION = "detect_motion_function"
DEFAULT_CLIENT_STREAM_FUNCTION = "client_stream_function"
DEFAULT_CLIENT_STREAM_MAX_CONNECTIONS = 5
DEFAULT_CLIENT_STREAM_TIMEOUT = 5

# Global variables
camera: Optional[cv2.VideoCapture] = None
client_streams: List[Tuple[str, Callable[[cv2.VideoCapture], None]]] = []

# Function to initialize the camera
def initialize_camera(width: int, height: int, framerate: int) -> None:
    """Initializes the camera with error handling and resource management."""
    global camera
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Could not open camera")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, width)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, height)
        camera.set(cv2.CAP_PROP_FPS, framerate)
        logging.info(f"Camera initialized successfully with width={width}, height={height}, framerate={framerate}")
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        raise

# Function to decode a JPEG frame
def decode_jpeg_frame(frame: cv2.Mat) -> Optional[cv2.Mat]:
    """Decodes a JPEG frame from a NumPy array."""
    try:
        jpeg_data = frame.tobytes()
        img = Image.open(io.BytesIO(jpeg_data)).convert('RGB')
        img = img.resize((width, height), Image.NEAREST)
        img = np.array(img, dtype=np.uint8)
        return cv2.cvtColor(img, cv2.COLOR_RGB2BGR)
    except Exception as e:
        logging.error(f"Error decoding JPEG frame: {e}")
        return None

# Function to detect motion
def detect_motion(prev_frame: cv2.Mat, curr_frame: cv2.Mat) -> bool:
    """Detects motion between two frames."""
    try:
        if prev_frame is None or curr_frame is None:
            return False

        diff = cv2.absdiff(prev_frame, curr_frame)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
        contours = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        for contour in contours:
            if cv2.contourArea(contour) < 500:
                continue
            x, y, w, h = cv2.boundingRect(contour)
            cv2.rectangle(curr_frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
        return True
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return False

# Function to handle client stream requests
def handle_client_stream(client_stream: Callable[[cv2.VideoCapture], None], client_stream_id: int, client_stream_data: bytes) -> None:
    """Handles a client stream request by broadcasting data."""
    try:
        if client_stream_id < len(client_streams):
            client_stream(client_streams[client_stream_id], client_stream_data)
