#!/usr/bin/env python3

import time
import smbus
import Adafruit_DHT

# Configuration
DHT_PIN = 4  # GPIO pin for DHT22 data
LCD_SCL_PIN = 3  # I2C SCL pin
LCD_SDA_PIN = 2  # I2C SDA pin
UPDATE_INTERVAL = 2  # Seconds between updates

# Initialize I2C bus
try:
    bus = smbus.SMBus(1)  # Use I2C bus 1
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    exit(1)

# Initialize LCD
try:
    lcd = Adafruit_DHT.DHT22_I2C(bus, LCD_SCL_PIN, LCD_SDA_PIN)
except Exception as e:
    print(f"Error initializing LCD: {e}")
    exit(1)

def read_dht22():
    """Reads temperature and humidity from the DHT22 sensor."""
    try:
        humidity, temperature = Adafruit_DHT.read_retry(Adafruit_DHT.DHT22, DHT_PIN)
        if humidity is not None and temperature is not None:
            return temperature, humidity
        else:
            print("Failed to read DHT22 sensor.")
            return None, None
    except Exception as e:
        print(f"Error reading DHT22 sensor: {e}")
        return None, None

def display_data(temperature, humidity):
    """Displays temperature and humidity on the LCD."""
    try:
        lcd.clear()
        lcd.write_string("Temp: ")
        lcd.write_string(f"{temperature:.1f}C")
        lcd.write_string(" ")
        lcd.write_string(f"Humidity: {humidity:.1f}%")
        lcd.write_string(" ")
    except Exception as e:
        print(f"Error displaying data on LCD: {e}")

def main():
    """Main function to continuously read and display sensor data."""
    while True:
        temperature, humidity = read_dht22()
        if temperature is not None and humidity is not None:
            display_data(temperature, humidity)
            time.sleep(UPDATE_INTERVAL)
        else:
            print("Failed to read sensor data after multiple attempts.")
            time.sleep(UPDATE_INTERVAL)

if __name__ == "__main__":
    main()

