#!/usr/bin/env python3

import time
import spidev
import RPi.GPIO as GPIO
import random

# Define SPI parameters
SPI_BUS = 0
SPI_DEVICE = 0
SPI_CS = 0

# Define GPIO pins
RST_PIN = 17
DC_PIN = 25
BUSY_PIN = 24

# Define SPI transaction parameters
SPI_SPEED_HZ = 1000000  # 1 MHz
SPI_MAX_RETRIES = 3

# Define SPI transfer function
def spi_transfer(spi, tx_data, tx_length):
    """Sends data to the e-Paper HAT over SPI."""
    try:
        spi.xfer2([tx_data])
        return True
    except Exception as e:
        print(f"SPI transfer failed: {e}")
        return False

# Define SPI transfer function
def spi_read(spi, tx_data, tx_length):
    """Reads data from the e-Paper HAT over SPI."""
    try:
        spi.xfer2([tx_data])
        return True
    except Exception as e:
        print(f"SPI read failed: {e}")
        return False

# Define SPI transfer function
def spi_write(spi, tx_data, tx_length):
    """Writes data to the e-Paper HAT over SPI."""
    try:
        spi.xfer2([tx_data])
        return True
    except Exception as e:
        print(f"SPI write failed: {e}")
        return False

# Define SPI transfer function
def spi_read_write(spi, tx_data, tx_length, rx_data, rx_length):
    """Reads and writes data to the e-Paper HAT over SPI."""
    try:
        spi_transfer(spi, tx_data, tx_length)
        spi_transfer(spi, rx_data, rx_length)
        return True
    except Exception as e:
        print(f"SPI read/write failed: {e}")
        return False

# Define SPI transfer function
def spi_read_write_block(spi, tx_data, tx_length, rx_data, rx_length):
    """Reads and writes data to the e-Paper HAT in blocks over SPI."""
    try:
        spi_transfer(spi, tx_data, tx_length)
        spi_transfer(spi, rx_data, rx_length)
        return True
    except Exception as e:
        print(f"SPI block read/write failed: {e}")
        return False

