def spi_write_block(spi, tx_data, tx_length, rx_data, rx_length):
    """Writes data to the e-Paper HAT in blocks over SPI."""
    try:
        spi_write(spi, tx_data, tx_length)
        return True
    except Exception as e:
        print(f"SPI block write failed: {e}")
        return False

# Define SPI transfer function
def spi_read_write_block_with_retries(spi, tx_data, tx_length, rx_data, rx_length, max_retries=3):
    """Reads and writes data to the e-Paper HAT in blocks with retries over SPI."""
    for attempt in range(max_retries):
        if spi_read_write_block(spi, tx_data, tx_length, rx_data, rx_length):
            return True
        else:
            print(f"SPI block read/write attempt {attempt + 1} failed. Retrying...")
            time.sleep(0.1)  # Short delay before retrying
    print(f"SPI block read/write attempt {max_retries} failed after {max_retries} attempts.")
    return False

# Define SPI transfer function
def spi_read_write_block_with_timeout(spi, tx_data, tx_length, rx_data, rx_length, timeout_ms=1000):
    """Reads and writes data to the e-Paper HAT in blocks with timeouts over SPI."""
    start_time = time.time()
    while time.time() - start_time < timeout_ms:
        if spi_read_write_block(spi, tx_data, tx_length, rx_data, rx_length):
            return True
        else:
            print(f"SPI block read/write timeout: Timeout after {timeout_ms} ms.")
            time.sleep(0.1)  # Short delay before retrying
    print(f"SPI block read/write timeout after {timeout_ms} ms.")
    return False

# Define SPI transfer function
def spi_read_write_block_with_retries_timeout(spi, tx_data, tx_length, rx_data, rx_length, max_retries=3, timeout_ms=1000):
    """Reads and writes data to the e-Paper HAT in blocks with retries and timeouts over SPI."""
    for attempt in range(max_retries):
        if spi_read_write_block_with_timeout(spi, tx_data, tx_length, rx_data, rx_length):
