#!/usr/bin/env python3

import RPi.GPIO as GPIO
import time
import logging
import math
import numpy as np

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
MOTOR_LEFT_PIN = 12
MOTOR_RIGHT_PIN = 18
MOTOR_PWM_LEFT = GPIO.PWM(MOTOR_LEFT_PIN, 50)
MOTOR_PWM_RIGHT = GPIO.PWM(MOTOR_RIGHT_PIN, 50)
MOTOR_PWM_LEFT.start(0)
MOTOR_PWM_RIGHT.start(0)
MAX_MOTOR_SPEED = 100

# Global variables
ball = None
car_front = None
car_back = None
goal = None

# GPIO setup
GPIO.setmode(GPIO.BCM)
GPIO.setup(MOTOR_LEFT_PIN, GPIO.OUT)
GPIO.setup(MOTOR_RIGHT_PIN, GPIO.OUT)

# Function to control a DC motor
def control_motor(motor_pin, duty_cycle, pwm):
    """Controls the speed of a DC motor connected to a PWM pin."""
    try:
        pwm.ChangeDutyCycle(duty_cycle)
        logging.info(f"Motor {motor_pin} duty cycle set to {duty_cycle}")
    except Exception as e:
        logging.error(f"Error controlling motor {motor_pin}: {e}")

# Function to calculate the distance between two points
def distance(point1, point2):
    """Calculates the Euclidean distance between two points in a 2D plane."""
    return np.sqrt((point1[0] - point2[0])**2 + (point1[1] - point2[1])**2)

# Function to calculate the heading angle between two points
def heading(point1, point2):
    """Calculates the heading angle between two points in a 2D plane."""
    return math.atan2(point1[1] - point2[1], point1[0] - point2[0])

# Function to calculate the angle between two lines
def angle_between_lines(line1, line2):
    """Calculates the angle between two lines in a 2D plane."""
    return math.degrees(math.atan2(line2[1] - line1[1], line2[0] - line1[0]))

# Function to calculate the distance to the goal
def distance_to_goal(car_front, car_back, goal):
    """Calculates the distance to the goal from the car's front and back."""
    return distance(car_front, goal) + distance(car_back, goal)

# Function to calculate the distance to the nearest point on the line
def distance_to_nearest_point(line, point):
    """Calculates the distance to the nearest point on a line."""
    return min(distance(point, line[0]), distance(point, line[1]))

# Function to calculate the distance to the nearest point on the ball-goal line
def distance_to_ball_goal(ball, goal):
    """Calculates the distance to the nearest point on the ball-goal line."""
    return min(distance(ball, goal), distance(ball, (0,0)))

# Function to calculate the distance to the nearest point on the ball-car line
def distance_to_ball_car(ball, car_front, car_back):
    """Calculates the distance to the nearest point on the ball-car line."""
    return min(distance(ball, car_front), distance(ball, car_back))

# Function to calculate the distance to the nearest point on the ball-goal line
def distance_to_ball_goal_line(ball, goal):
    """Calculates the distance to the nearest point on the ball-goal line."""
