import os
import time
from gpiozero import CPUTemperature

def get_cpu_temperature():
    """Reads the CPU temperature and returns it as a float.

    Handles potential errors during temperature reading, such as file not found.
    """
    try:
        temp = CPUTemperature()
        return temp.temperature
    except FileNotFoundError:
        print("Error: No thermal sensor found. Check your wiring.")
        return None
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

if __name__ == "__main__":
    try:
        while True:
            cpu_temp = get_cpu_temperature()
            if cpu_temp is not None:
                print(f"CPU Temperature: {cpu_temp:.2f} °C")
            time.sleep(5)
    except KeyboardInterrupt:
        print("\nProgram terminated")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

