logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# I2C bus configuration
I2C_BUS = 1

# BME280 I2C address
BME280_ADDRESS = 0x76

# Temperature and humidity thresholds
TEMP_THRESHOLD = 21.0
HUMIDITY_THRESHOLD = 50

# CSV file name
CSV_FILE = 'store_environment.csv'

# Initialize I2C bus
try:
    bus = smbus.SMBus(I2C_BUS)
except Exception as e:
    logging.error(f"Error initializing I2C bus: {e}")
    exit(1)

def read_bme280_data():
    """Reads temperature and humidity from the BME280 sensor."""
    try:
        # Simulate sensor data (replace with actual sensor reading)
        temperature = random.uniform(20.0, 26.0)
        humidity = random.uniform(35.0, 55.0)
        return temperature, humidity
    except Exception as e:
        logging.error(f"Error reading BME280 sensor: {e}")
        return None, None

def calculate_comfort_level(temperature, humidity):
    """Calculates the comfort level based on temperature and humidity."""
    if temperature is None or humidity is None:
        return "N/A"

    if TEMP_THRESHOLD <= temperature <= TEMP_THRESHOLD + 2.0:
        comfort = "COMFORTABLE"
    elif temperature > TEMP_THRESHOLD + 2.0:
        comfort = "TOO_WARM"
    else:
        comfort = "ACCEPTABLE"

    if humidity is None or humidity <= HUMIDITY_THRESHOLD:
        comfort = "ACCEPTABLE"
    elif humidity > HUMIDITY_THRESHOLD + 5.0:
        comfort = "TOO_WARM"
    else:
        comfort = "COMFORTABLE"

    return comfort

def log_data(timestamp, temperature, humidity, comfort):
    """Logs the sensor data to a CSV file."""
    try:
        with open(CSV_FILE, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, temperature, humidity, comfort])
    except Exception as e:
        logging.error(f"Error writing to CSV file: {e}")

def main():
    """Main function to monitor temperature and humidity and log data."""
    try:
        for _ in range(10):
            temperature, humidity = read_bme280_data()
            if temperature is not None and humidity is not None:
                comfort = calculate_comfort_level(temperature, humidity)
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_data(timestamp, temperature, humidity, comfort)
                print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%, Comfort: {comfort}")
            else:
                print("Failed to read sensor data. Skipping this iteration.")
            time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Clean up resources
        try:
            bus.close()
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
        print("I2C bus closed.")

if __name__ == "__main__":
    main()

