            time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Clean up resources
        try:
            bus.close()
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
        print("I2C bus closed.")

