# air_quality_monitor.py
# A simple air quality monitor for Raspberry Pi using a BME680 sensor.
# Reads data from the BME680 sensor, logs it to a file, and prints it to the console.

import time
import board
import busio
import adafruit_bme680
import datetime

# Configuration
SENSOR_ID = 0  # BME680 sensor ID
LOG_FILE = "air_quality_log.txt"
READ_INTERVAL = 10  # seconds

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the BME680 sensor."""
    try:
        sensor = adafruit_bme680.Adafruit_BME680_I2C(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error initializing BME680 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads temperature, humidity, pressure, and gas resistance from the sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        pressure = sensor.pressure
        gas_resistance = sensor.gas_resistance
        return temperature, humidity, pressure, gas_resistance
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None, None

def log_data(timestamp, temperature, humidity, pressure, gas_resistance):
    """Logs the sensor data to a file."""
    try:
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"{timestamp},Temperature: {temperature:.2f}C,Humidity: {humidity:.2f}%,Pressure: {pressure:.2f}hPa,Gas Resistance: {gas_resistance:.2f} ohms\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log air quality data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            temperature, humidity, pressure, gas_resistance = read_sensor_data(sensor)

            if temperature is not None and humidity is not None and pressure is not None and gas_resistance is not None:
                log_data(timestamp, temperature, humidity, pressure, gas_resistance)
            else:
                print("Skipping data logging due to sensor read errors.")

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure clean resource release
        print("Cleaning up resources...")
        if i2c_bus:
            i2c_bus.deinit()
        if sensor:
            sensor.deinit()
        print("Program terminated.")

if __name__ == "__main__":
    main()

