import smbus
import time
import datetime
import sqlite3
import logging
import threading
import json
import flask
import RPi.GPIO as GPIO
from flask import Flask, render_template, Response, request, jsonify

# Configure logging
logging.basicConfig(filename="/home/pi/wearable_sensor.log", level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
running = True
data_thread = None
bme280_bus = None

# Flask app setup
app = Flask(__name__)

# Database setup
DATABASE_PATH = "/home/pi/wearable_data.db"

# I2C setup
def setup_i2c():
    global bme280_bus
    try:
        bme280_bus = smbus.SMBus(1)  # Use I2C bus 1
        logging.info("I2C bus initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        raise

# Sensor reading function
def read_sensor_data():
    global running
    try:
        # Read temperature, humidity, and pressure from the BME280 sensor
        temperature = bme280_bus.read_byte_data(0x88, 0xF4)
        humidity = bme280_bus.read_byte_data(0x88, 0xF5)
        pressure = bme280_bus.read_byte_data(0x88, 0xF6)

        # Validate sensor readings
        if not (-40 <= temperature <= 85 and 0 <= humidity <= 100 and 30_000 <= pressure <= 110_000):
            logging.warning(f"Invalid sensor reading: Temperature={temperature:.2f}°C, Humidity={humidity:.2f}%, Pressure={pressure:.2f} Pa")
            return None, None, None

        # Store the sensor data in the database
        timestamp = datetime.datetime.now().isoformat()
        data = {
            "timestamp": timestamp,
            "temperature": temperature,
            "humidity": humidity,
            "pressure": pressure
        }
        try:
            conn = sqlite3.connect(DATABASE_PATH)
            cursor = conn.cursor()
            cursor.execute("INSERT INTO sensor_data (timestamp, temperature, humidity, pressure) VALUES (?, ?, ?, ?)", (data["timestamp"], data["temperature"], data["humidity"], data["pressure"]))
            conn.commit()
            conn.close()
        except sqlite3.Error as e:
            logging.error(f"Database error: {e}")
        return temperature, humidity, pressure
    except Exception as e:
        logging.error(f"Error reading sensor data: {e}")
        return None, None, None

# Data validation function
def validate_data(temperature, humidity, pressure):
    if not (-40 <= temperature <= 85 and 0 <= humidity <= 100 and 30_000 <= pressure <= 110_000):
        logging.warning(f"Invalid data validation: Temperature={temperature:.2f}°C, Humidity={humidity:.2f}%, Pressure={pressure:.2f} Pa")
        return False
    return True

