    timestamp = datetime.datetime.now().isoformat()
    data = {
        "timestamp": timestamp,
        "temperature": temperature,
        "humidity": humidity,
        "pressure": pressure
    }
    try:
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()
        cursor.execute("INSERT INTO sensor_data (timestamp, temperature, humidity, pressure) VALUES (?, ?, ?, ?)", (data["timestamp"], data["temperature"], data["humidity"], data["pressure"]))
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

# Data storage function
def store_data(temperature, humidity, pressure):
    timestamp = datetime.datetime.now().isoformat()
    data = {
        "timestamp": timestamp,
        "temperature": temperature,
        "humidity": humidity,
        "pressure": pressure
    }
    try:
