# temperature/humidity sensor reader for Raspberry Pi
# Reads temperature and humidity from a UART sensor and prints it

import serial
import time

# Serial port configuration for the UART sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Temperature and humidity thresholds
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def initialize_uart(port, baud):
    """Initializes the UART connection."""
    try:
        ser = serial.Serial(port, baud, timeout=TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing UART: {e}")
        return None

def read_sensor_data(ser):
    """Reads temperature and humidity from the sensor."""
    try:
        line = ser.readline().decode('ascii', errors='replace').strip()
        if line:
            temp, humidity = line.split(',')
            return float(temp), float(humidity)
        return None, None
    except ValueError:
        print("Invalid sensor data format.")
        return None, None
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if temperature and humidity exceed thresholds."""
    if temperature is not None and humidity is not None:
        if temperature > TEMPERATURE_THRESHOLD:
            print(f"Temperature exceeds threshold: {temperature:.2f}°C")
        if humidity > HUMIDITY_THRESHOLD:
            print(f"Humidity exceeds threshold: {humidity:.2f}%")

def main():
    """Main function to read sensor data and print it."""
    ser = initialize_uart(SERIAL_PORT, BAUD_RATE)
    if ser is None:
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(ser)
            check_thresholds(temperature, humidity)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        ser.close()
        print("UART connection closed.")

if __name__ == "__main__":
    main()

