import RPi.GPIO as GPIO
import time
import requests
import json

# Define GPIO pin for the digital sensor
SENSOR_PIN = 4

# Define the HTTP endpoint for the server
SERVER_ENDPOINT = "http://localhost:5000/sensor"

# Define the user and password for authentication
USERNAME = "admin"
PASSWORD = "password"

def initialize_gpio():
    """Initializes the GPIO pins for the digital sensor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

def read_sensor_value():
    """Reads the value from the digital sensor."""
    return GPIO.input(SENSOR_PIN)

def send_sensor_data(sensor_value):
    """Sends the sensor data to the server."""
    try:
        data = {"sensor": "digital_input", "value": sensor_value}
        headers = {"Content-type": "application/json"}
        response = requests.post(SERVER_ENDPOINT, json=data, auth=(USERNAME, PASSWORD), headers=headers)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        print(f"Sensor data sent successfully. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Error sending sensor data: {e}")

def main():
    """Main function to read sensor data and send it to the server."""
    try:
        initialize_gpio()
        while True:
            sensor_value = read_sensor_value()
            send_sensor_data(sensor_value)
            time.sleep(5)  # Wait 5 seconds before the next reading
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

