#!/usr/bin/env python3

import RPi.GPIO as GPIO
import time

# Define GPIO pins
STEP_PIN = 21
DIR_PIN = 20

# Define pulse train parameters
PULSE_LENGTH = 15625  # µs
PULSE_COUNT = 1600

# Define direction change sequence
DIRECTION_CHANGE_SEQUENCE = [0, 1, 0, 1]

def initialize_gpio(step_pin, dir_pin):
    """Initialize GPIO pins with error handling and cleanup."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(step_pin, GPIO.OUT)
        GPIO.setup(dir_pin, GPIO.OUT)
        GPIO.output(step_pin, GPIO.HIGH)  # Initial direction
        return True
    except Exception as e:
        print(f"GPIO initialization error: {e}")
        return False

def generate_pulse(step_pin, pulse_length, pulse_count):
    """Generate a single pulse on the step pin."""
    try:
        for _ in range(pulse_count):
            GPIO.output(step_pin, GPIO.HIGH)
            time.sleep(pulse_length / 1000000.0)
            GPIO.output(step_pin, GPIO.LOW)
            time.sleep(pulse_length / 1000000.0)
    except Exception as e:
        print(f"Error generating pulse: {e}")

def change_direction(step_pin, dir_pin, direction_sequence):
    """Change the direction of the step pin."""
    try:
        GPIO.output(dir_pin, direction_sequence[0])
        time.sleep(0.1)
        GPIO.output(step_pin, GPIO.HIGH)
        time.sleep(PULSE_LENGTH)
        GPIO.output(step_pin, GPIO.LOW)
        time.sleep(PULSE_LENGTH)
        GPIO.output(dir_pin, direction_sequence[1])
        time.sleep(0.1)
    except Exception as e:
        print(f"Error changing direction: {e}")

def run_pulse_train(step_pin, dir_pin, pulse_count, pulse_length):
    """Run a single pulse train."""
    try:
        generate_pulse(step_pin, pulse_length, pulse_count)
        change_direction(step_pin, dir_pin, DIRECTION_CHANGE_SEQUENCE)
    except Exception as e:
        print(f"Error during pulse train: {e}")

def run_pulse_sequence(step_pin, dir_pin, pulse_count, pulse_length):
    """Run a sequence of pulse trains."""
    try:
        for _ in range(2):
            run_pulse_train(step_pin, dir_pin, pulse_count, pulse_length)
    except Exception as e:
        print(f"Error during pulse sequence: {e}")

def main():
    """Main function to initialize and run the pulse train."""
    if not initialize_gpio(STEP_PIN, DIR_PIN):
        return

    try:
        run_pulse_sequence(STEP_PIN, DIR_PIN, PULSE_COUNT, PULSE_LENGTH)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

