import serial
import time
import RPi.GPIO as GPIO

# Constants for servo control
SERVO_PIN = 17
BAUD_RATE = 9600
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_TIMEOUT = 1

# Servo calibration values (adjust these for your servo)
MIN_ANGLE = 0
MAX_ANGLE = 180

def initialize_serial(port, baud):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=SERIAL_TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for servo control."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)

def set_servo_angle(servo, angle):
    """Sets the angle of the servo motor."""
    try:
        duty_cycle = (angle / 180) * 2.5
        servo.output(duty_cycle)
        time.sleep(0.5)  # Allow time for the servo to move
    except ValueError as e:
        print(f"Invalid angle: {e}")
    except Exception as e:
        print(f"Error setting servo angle: {e}")

def read_angle(ser):
    """Reads an angle from the serial port."""
    try:
        line = ser.readline().decode('ascii', errors='replace').strip()
        if line:
            return int(line)
        return None
    except ValueError as e:
        print(f"Invalid serial input: {e}")
        return None

def main():
    """Main function to control the servo."""
    ser = initialize_serial(SERIAL_PORT, BAUD_RATE)
    if ser is None:
        return

    initialize_gpio(SERVO_PIN)

    try:
        while True:
            angle = read_angle(ser)
            if angle is not None:
                set_servo_angle(ser, angle)
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        ser.close()
        GPIO.cleanup()
        print("Resources cleaned up.")

if __name__ == "__main__":
    main()

