#!/usr/bin/env python3

import serial
import time
import RPi.GPIO as GPIO
import threading
import logging
import sys

# Configure logging
logging.basicConfig(filename='seed_sorter.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600

# GPIO pin configuration
SLEEP_DURATION = 0.5
DEAD_TIME = 0.2

# Safety limit
SLEEP_LIMIT = 1

# Global variables
serial_port = None
solenoid_active = False
solenoid_start_time = None

def initialize_gpio():
    """Initializes GPIO pins for solenoid control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SLEEP_PIN, GPIO.OUT)
        GPIO.output(SLEEP_PIN, GPIO.LOW)
        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        sys.exit(1)

def initialize_serial(port, baudrate):
    """Initializes the serial port."""
    try:
        global serial_port
        serial_port = serial.Serial(port, baudrate, timeout=1)
        logging.info(f"Serial port {port} initialized successfully.")
    except serial.SerialException as e:
        logging.error(f"Error opening serial port {port}: {e}")
        sys.exit(1)

def read_weight_data(serial_port):
    """Reads weight data from the serial scale and returns the weight in grams."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                weight = float(line)
                return weight
            except ValueError:
                logging.warning(f"Invalid weight data: {line}")
                return None
        else:
            logging.warning("No data received from serial port.")
            return None
    except serial.SerialException as e:
        logging.error(f"Error reading from serial port: {e}")
        return None
    except Exception as e:
        logging.error(f"Error processing weight data: {e}")
        return None

def control_solenoid(solenoid_pin, solenoid_active):
    """Controls the solenoid based on the solenoid_active flag."""
    if solenoid_active:
        try:
            GPIO.output(solenoid_pin, GPIO.HIGH)
            logging.info("Solenoid activated.")
        except Exception as e:
            logging.error(f"Error controlling solenoid: {e}")
    else:
        try:
            GPIO.output(solenoid_pin, GPIO.LOW)
            logging.info("Solenoid deactivated.")
        except Exception as e:
            logging.error(f"Error controlling solenoid: {e}")

def solenoid_activation_duration(solenoid_pin, solenoid_active):
    """Measures the duration of solenoid activation."""
    if solenoid_active:
        start_time = time.time()
        while GPIO.input(solenoid_pin) == GPIO.LOW:
            time.sleep(0.01)  # Small delay to avoid busy-waiting
            start_time = time.time()
        end_time = time.time()
        return end_time - start_time
    else:
        return None

def main():
    """Main function to run the seed sorting program."""
    global serial_port, solenoid_active, solenoid_start_time

    try:
        initialize_gpio()
        initialize_serial(SERIAL_PORT, BAUD_RATE)

        # Initialize solenoid state
        solenoid_active = False
        solenoid_start_time = None

        # Start solenoid control thread
        solenoid_thread = threading.Thread(target=solenoid_activation_duration, args=(SLEEP_PIN, solenoid_active), daemon=True)
        solenoid_thread.start()

        while True:
            try:
                weight_data = read_weight_data(serial_port)

                if weight_data is not None:
                    if weight_data > 0.25:
                        if not solenoid_active:
                            control_solenoid(SLEEP_PIN, True)
                            solenoid_active = True
                            solenoid_start_time = time.time()
                            logging.info("Solenoid activated.")
                        else:
                            logging.warning("Solenoid already active.")
                    else:
                        if solenoid_start_time is not None and (time.time() - solenoid_start_time) > SLEEP_LIMIT:
                            control_solenoid(SLEEP_PIN, False)
                            solenoid_active = False
                            solenoid_start_time = None
                            logging.info("Solenoid deactivated.")
                else:
                    logging.warning("No weight data received.")

            except serial.SerialException as e:
                logging.error(f"Serial communication error: {e}")
                time.sleep(1)  # Wait before retrying
            except Exception as e:
                logging.error(f"An unexpected error occurred: {e}")
                time.sleep(1)  # Wait before retrying

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
