import smbus
import datetime
import contextlib

# Constants for DS1338 register addresses
DS1338_ADDRESS = 0x68
REG_CH = 0x7F
REG_SECOND = 0x7E
REG_MINUTE = 0x7D
REG_HOUR = 0x7C
REG_DAY = 0x7B
REG_MONTH = 0x7A
REG_YEAR = 0x79
REG_CONTROL = 0x7F

class DS1338Error(Exception):
    """Custom exception for DS1338 related errors."""
    pass

class DS1338:
    """Driver class for Maxim DS1338 real-time clock."""

    def __init__(self, i2c_bus_number=1, address=DS1338_ADDRESS):
        """
        Initializes the DS1338 driver.

        Args:
            i2c_bus_number (int): The I2C bus number.
            address (int): The I2C address of the DS1338.
        """
        self.i2c_bus_number = i2c_bus_number
        self.address = address
        self.bus = None  # Initialize to None

    def __enter__(self):
        """Context manager entry."""
        self.bus = smbus.SMBus(self.i2c_bus_number)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit."""
        if self.bus:
            self.bus.close()

    def close(self):
        """Closes the I2C bus."""
        if self.bus:
            self.bus.close()

    def read_all(self):
        """Reads all registers."""
        try:
            for register in range(0x7F, -1, -1):
                self.bus.read_byte_data(self.address, register)
        except IOError as e:
            raise DS1338Error(f"Error reading DS1338 registers: {e}")

    def read_byte(self, register):
        """Reads a byte from a register."""
        try:
            return self.bus.read_byte_data(self.address, register)
        except IOError as e:
            raise DS1338Error(f"Error reading DS1338 register {register}: {e}")

    def read_word(self, register):
        """Reads a word from a register."""
        try:
            return self.bus.read_word_data(self.address, register)
        except IOError as e:
            raise DS1338Error(f"Error reading DS1338 register {register}: {e}")

    def read_word_data(self, register):
        """Reads a word of data from a register."""
        try:
            return self.bus.read_word_data(self.address, register)
        except IOError as e:
            raise DS1338Error(f"Error reading DS1338 register {register}: {e}")

    def read_all_registers(self):
        """Reads all registers in one go."""
        self.read_all()

    def read_datetime(self):
        """Reads the current date and time."""
        try:
            year = self.read_word_data(REG_SECOND) & 0x0FF
            month = self.read_word_data(REG_SECOND + 2) & 0x0FF
            date = self.read_word_data(REG_SECOND + 4) & 0x0FF
            day = self.read_word_data(REG_SECOND + 6) & 0x0FF
            hours = self.read_byte_data(REG_HOUR)
            minutes = self.read_byte_data(REG_MINUTE)
            seconds = self.read_byte_data(REG_SECOND)
            ch = self.read_byte_data(REG_CH)

            if ch & 0x80:
                hours = 12 + hours - 12
            if ch & 0x40:
                minutes = 60 - minutes + 12
            if ch & 0x20:
                seconds = 60 - seconds + 12

            return datetime.datetime(year, month, date, hours, minutes, seconds)

        except DS1338Error as e:
            raise e

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Writes all registers."""
        try:
            self.write_byte_data(REG_SECOND, (year & 0xFF) | 0x80)
            self.write_byte_data(REG_MINUTE, (month & 0xFF))
            self.write_byte_data(REG_HOUR, hours & 0xFF)
            self.write_byte_data(REG_MINUTE, minutes & 0xFF)
            self.write_byte_data(REG_SECOND, seconds & 0xFF)
            self.write_byte_data(REG_CH, (hours >= 12) | (minutes >= 30) | (seconds >= 1))
        except DS1338Error as e:
            raise e

    def write_byte(self, register, value):
        """Writes a byte to a register."""
        try:
            self.bus.write_byte_data(self.address, register, value)
        except IOError as e:
            raise DS1338Error(f"Error writing DS1338 register {register}: {e}")

    def write_word(self, register, value):
        """Writes a word to a register."""
        try:
            self.bus.write_word_data(self.address, register, value)
        except IOError as e:
            raise DS1338Error(f"Error writing DS1338 register {register}: {e}")

    def write_word_data(self, register, value):
        """Writes a word of data to a register."""
        try:
            self.bus.write_word_data(self.address, register, value)
        except IOError as e:
            raise DS1338Error(f"Error writing DS1338 register {register}: {e}")

    def write_all_registers(self, year, month, date, day, hours, minutes, seconds):
        """Writes all registers in one go."""
        self.write_all()
        self.write_byte(REG_SECOND, (year & 0xFF) | 0x80)
        self.write_byte(REG_MINUTE, (month & 0xFF))
        self.write_byte(REG_HOUR, hours & 0xFF)
        self.write_byte(REG_MINUTE, minutes & 0xFF)
        self.write_byte(REG_SECOND, seconds & 0xFF)
        self.write_byte(REG_CH, (hours >= 12) | (minutes >= 30) | (seconds >= 1))

    def close(self):
        """Closes the I2C bus."""
        if self.bus:
            self.bus.close()


# Example usage (replace with your actual initialization):
if __name__ == "__main__":
    try:
        driver = DS1338()
        # ... (rest of the initialization code)

        # Demonstrate reading and writing
        now = driver.read_datetime()
        print(f"Current date and time: {now}")

        driver.write_all(2000, 1, 1, 1, 0, 0, 0)
        now = driver.read_datetime()
        print(f"Now: {now}")

    except DS1338Error as e:
        print(f"DS1338 error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

