#!/usr/bin/env python3

import RPi.GPIO as GPIO
import time
import datetime
import json
import logging
import os
import subprocess

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pin for OOK transmission
GPIO_PIN = 17

# Define configuration file path
CONFIG_FILE = 'irrigation_config.json'

# Define default configuration values
DEFAULT_CONFIG = {
    'zone1_on': False,
    'zone1_off': False,
    'zone2_on': False,
    'zone2_off': False,
    'gpio_pin': 17,
    'transmission_repeat': 3
}

def load_config(config_file):
    """Loads the configuration from a JSON file."""
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        return DEFAULT_CONFIG
    except json.JSONDecodeError:
        logging.error(f"Error decoding JSON in {config_file}")
        return DEFAULT_CONFIG

def save_config(config, config_file):
    """Saves the configuration to a JSON file."""
    try:
        with open(config_file, 'w') as f:
            json.dump(config, f, indent=4)
    except IOError as e:
        logging.error(f"Error saving configuration to {config_file}: {e}")

def get_zone_state(zone):
    """Retrieves the state of a zone from the configuration."""
    try:
        zone_state = config.get(zone)
        if zone_state is None:
            return DEFAULT_CONFIG.get(zone)  # Default to off if zone not found
        return zone_state
    except (KeyError, TypeError):
        logging.error(f"Error getting zone state for {zone}. Using default.")
        return DEFAULT_CONFIG.get(zone)

def set_zone_state(zone, state):
    """Sets the state of a zone in the configuration."""
    try:
        config[zone] = state
        save_config(config, CONFIG_FILE)
        logging.info(f"Zone {zone} set to {state}")
    except KeyError:
        logging.error(f"Error setting zone state: {zone} is not in the configuration.")
    except Exception as e:
        logging.error(f"Error setting zone state: {e}")

def transmit_zone(zone, on):
    """Transmits the RF code for a specific zone."""
    try:
        # OOK modulation
        GPIO.output(GPIO_PIN, GPIO.HIGH)
        time.sleep(0.001)
        GPIO.output(GPIO_PIN, GPIO.LOW)
        time.sleep(0.001)

        # Transmit the RF code
        for bit in str(on).zfill(8):
            GPIO.output(GPIO_PIN, GPIO.HIGH)
            time.sleep(0.001)
            GPIO.output(GPIO_PIN, GPIO.LOW)
            time.sleep(0.001)

        # Repeat the transmission
        for _ in range(config.get('transmission_repeat', 3)):
            GPIO.output(GPIO_PIN, GPIO.HIGH)
            time.sleep(0.001)
            GPIO.output(GPIO_PIN, GPIO.LOW)
            time.sleep(0.001)

    except Exception as e:
        logging.error(f"Error transmitting RF code for zone {zone}: {e}")

def main():
    """Main function to handle user input and control the irrigation system."""
    try:
        # Load configuration
        config = load_config(CONFIG_FILE)

        # Get command-line arguments
        zone = None
        on = None
        while True:
            command = input("Enter command (zone1|zone2|on|off): ").lower()
            if command == 'zone1':
                zone = 'zone1'
            elif command == 'zone2':
                zone = 'zone2'
            elif command == 'on':
                on = True
            elif command == 'off':
                on = False
            elif command == 'exit':
                break
            else:
                logging.warning(f"Unknown command: {command}")

        # Check if zone is valid
        if zone:
            zone_state = get_zone_state(zone)
            if zone_state == on:
                set_zone_state(zone, on)
            else:
                logging.warning(f"Zone {zone} is already on.")
        else:
            logging.warning("No zone specified.")

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Clean up GPIO on exit
        GPIO.cleanup()
        logging.info("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

