import serial
import time
import RPi.GPIO as GPIO
import atexit

# Constants for Bluetooth connection
BLUETOOTH_PORT = '/dev/rfcomm4'
BLUETOOTH_BAUD_RATE = 38400
TIMEOUT = 1

# GPIO setup for reset button
GPIO.setmode(GPIO.BCM)
reset_pin = 17
GPIO.setup(reset_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

# Function to send commands to the Bluetooth device
def send_command(command):
    """Sends a command over the Bluetooth connection."""
    try:
        serial_port.write(command.encode('utf-8'))
        time.sleep(0.1)  # Add a small delay
    except serial.SerialException as e:
        raise RuntimeError(f"Error sending command: {e}")

# Function to handle user input and send commands
def handle_user_input():
    """Continuously prompts the user for commands."""
    try:
        while True:
            user_input = input("Enter command (or 'exit' to quit): ")
            if user_input.lower() == 'exit':
                print("Exiting...")
                break
            send_command(user_input)
    except KeyboardInterrupt:
        print("\nUser interrupted.")
    except RuntimeError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

# Function to handle Bluetooth connection and data transfer
def handle_bluetooth_connection():
    """Handles the Bluetooth connection and data transfer."""
    try:
        with serial.Serial(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE, timeout=TIMEOUT) as ser:
            print("Connected to Bluetooth device.")
            while True:
                try:
                    user_input = input("Enter command (or 'exit' to quit): ")
                    if user_input.lower() == 'exit':
                        break
                    send_command(user_input)
                except KeyboardInterrupt:
                    print("\nUser interrupted.")
                except RuntimeError as e:
                    print(f"Error: {e}")
                    break
                except Exception as e:
                    print(f"An unexpected error occurred: {e}")
                    break
    except serial.SerialException as e:
        print(f"Error: Could not open serial port {BLUETOOTH_PORT}: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Closing Bluetooth connection.")
        if 'ser' in locals() and ser.is_open:
            ser.close()
        GPIO.cleanup()  # Clean up GPIO on exit

# Main execution block
if __name__ == "__main__":
    atexit.register(handle_bluetooth_connection)
    try:
        print("Raspberry Pi Bluetooth control program started.")
        handle_user_input()
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Program finished.")

